package com.spms.controller;
import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import com.spms.entity.*;import com.spms.service.*;import java.time.*;import java.util.*;
@RestController @RequiredArgsConstructor public class DocumentController{private final DocumentService docs;
 @PostMapping("/api/admin/employees/{id}/documents")public EmployeeDocument upload(@PathVariable UUID id,@RequestParam String type,@RequestParam String title,@RequestParam(required=false)String issuer,@RequestParam(required=false)LocalDate issueDate,@RequestPart("file") MultipartFile file,Authentication a)throws Exception{return docs.upload(id,type,title,issuer,issueDate,file,a.getName());}
 @GetMapping("/api/admin/employees/{id}/documents")public List<EmployeeDocument> list(@PathVariable UUID id){return docs.list(id);}
 @GetMapping("/api/documents/{id}/download")public ResponseEntity<?> download(@PathVariable UUID id,Authentication a){var d=docs.get(id);var staff=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")||x.getAuthority().equals("ROLE_OWNER"));if(!staff&&!d.getEmployee().getUserAccount().getUsername().equals(a.getName()))return ResponseEntity.status(403).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+d.getOriginalName()+"\"").body(docs.resource(d));}}
